import { claudePromoAssets } from "./content";
const customizeImages = [
  "data:image/png;base64,",
  "data:image/png;base64,",
];

type TourShot = {
  title: string;
  src: string;
  alt: string;
  label: string;
  caption: string;
  width?: number;
  height?: number;
};
const tourGroups = [
  ["daily", "Daily execution"],
  ["health", "Health & training"],
  ["money", "Money & decisions"],
  ["business", "Business"],
  ["reflection", "Notes & reflection"],
  ["explore", "Hobbies & travel"],
  ["customize", "Make it yours"],
  ["ai", "Evo + AI Workflow"],
];
function TourShotCard({ title, src, alt, label, caption, width = 1440, height = 1000 }: TourShot) {
  return (
    <figure className="evo-tour-shot">
      <div className="evo-tour-shot-bar">
        <span>{label}</span>
        <Dialog>
          <DialogTrigger asChild>
            <button className="evo-tour-enlarge" aria-label={`Enlarge ${title} tour image`}>
              <Expand size={16} aria-hidden="true" /> Enlarge
            </button>
          </DialogTrigger>
          <DialogContent className="evo-tour-dialog">
            <DialogTitle>{title}</DialogTitle>
            <DialogDescription>
              {label}. {caption}
            </DialogDescription>
            <div className="evo-tour-detail" tabIndex={0} role="region" aria-label={`${title} image detail`}>
              <img src={src} alt={alt} width={width} height={height} />
            </div>
          </DialogContent>
        </Dialog>
      </div>
      <img src={src} alt={alt} width={width} height={height} loading="lazy" decoding="async" />
      <figcaption>
        <strong>{title}</strong>
        <p>{caption}</p>
      </figcaption>
    </figure>
  );
}
function TourFeatures({ items }: { items: [string, string][] }) {
  return (
    <dl className="evo-tour-features">
      {items.map(([title, copy]) => (
        <div key={title}>
          <dt>{title}</dt>
          <dd>{copy}</dd>
        </div>
      ))}
    </dl>
  );
}
function TourHeading({ n, title, copy }: { n: string; title: string; copy: string }) {
  return (
    <header className="evo-tour-chapter-heading">
      <p className="evo-tour-kicker">{n} / Inside Evolution OS</p>
      <h3>{title}</h3>
      <p>{copy}</p>
    </header>
  );
}
function TourDiagram({
  items,
  title,
}: {
  items: { icon: typeof Target; name: string; steps: string[] }[];
  title: string;
}) {
  return (
    <figure className="evo-tour-diagram">
      <figcaption>
        <span className="evo-tour-kicker">Feature guide · illustrated overview</span>
        <strong>{title}</strong>
      </figcaption>
      <div className="evo-tour-diagram-grid">
        {items.map(({ icon: Icon, name, steps }) => (
          <div className="evo-tour-diagram-card" key={name}>
            <Icon size={36} strokeWidth={1.35} aria-hidden="true" />
            <h4>{name}</h4>
            <ol>
              {steps.map((s) => (
                <li key={s}>{s}</li>
              ))}
            </ol>
          </div>
        ))}
      </div>
      <p className="evo-tour-diagram-note">A guide to the workflow, not a screenshot of the app.</p>
    </figure>
  );
}
